# Generated by scripts/submit_pr_a100.py; contains no credentials.
param(
    [ValidateSet('Generate', 'Smoke', 'Full')][string]$Phase = 'Smoke',
    [string]$KeyPath = 'C:\Users\v-guanhechen\.ssh\lidong\priv.openk',
    [string]$SshHost = '10.209.224.207',
    [string]$SshUser = 'lidong1@microsoft.com',
    [string]$RemoteProject = '',
    [string]$Campaign = 'pr-qwen35-a100-10n-v1-20261125'
)
$ErrorActionPreference = 'Stop'
if (-not (Test-Path -LiteralPath $KeyPath -PathType Leaf)) {
    throw "Private key not found on this Windows machine: $KeyPath"
}
Get-Command ssh -ErrorAction Stop | Out-Null
$options = @{
    phase = $Phase
    project = $RemoteProject
    campaign = $Campaign
} | ConvertTo-Json -Compress
$options64 = [Convert]::ToBase64String([Text.Encoding]::UTF8.GetBytes($options))
$python = @'
import base64, gzip, json, os, shutil, subprocess, sys
from pathlib import Path
options = json.loads(base64.b64decode('__OPTIONS__'))
script = gzip.decompress(base64.b64decode('__PAYLOAD__'))
folder = Path.home() / '.cache' / 'pr-a100-submission'
folder.mkdir(parents=True, exist_ok=True)
entry = folder / 'submit_pr_a100.py'
entry.write_bytes(script)
requested = options['project']
choices = [Path(requested).expanduser()] if requested else [
    Path.home() / 'rl', Path.home() / 'ytz' / 'rl', Path('/home/v-guanhechen/rl')]
project = next((p for p in choices if (p / '.amltconfig').is_file()), None)
if project is None:
    raise SystemExit('No AMLT project found. Set -RemoteProject to the directory containing .amltconfig.')
os.chdir(project)
if options['phase'] != 'Generate' and not shutil.which('amlt'):
    raise SystemExit('amlt is unavailable in the remote login PATH. Activate the AMLT environment there first.')
args = [sys.executable, str(entry), '--campaign', options['campaign'], '--output', str(folder / options['campaign'])]
if options['phase'] == 'Smoke': args += ['--smoke']
if options['phase'] != 'Generate': args += ['--submit']
print('SUBMISSION_PROJECT', project, flush=True)
subprocess.run(args, check=True)
'@
$python = $python.Replace('__OPTIONS__', $options64).Replace('__PAYLOAD__', '')
# Stream ASCII source on stdin, avoiding Windows PowerShell native-argument quote loss.
# User options remain base64 JSON, never shell command text.
$remoteCommand = "bash -lc 'python3 -'"
$sshArgs = @('-i', $KeyPath, '-o', 'IdentitiesOnly=yes', '-o', 'ConnectTimeout=15', '-l', $SshUser, $SshHost, $remoteCommand)
$python | & ssh @sshArgs
if ($LASTEXITCODE -ne 0) { throw "Remote submission failed with exit code $LASTEXITCODE" }
